CREATE OR REPLACE FUNCTION public.claim_first_contact(p_id uuid,p_lease uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.first_contact_settings; q public.first_contact_sequences; l public.leads; b text; BEGIN
 SELECT * INTO s FROM public.first_contact_settings WHERE company_key='crm:1' FOR UPDATE; SELECT * INTO q FROM public.first_contact_sequences WHERE id=p_id FOR UPDATE;
 IF q.id IS NULL OR q.state<>'pending' OR q.due_at>now() THEN RETURN NULL; END IF;
 SELECT * INTO l FROM public.leads WHERE id=q.lead_id FOR UPDATE;
 IF NOT coalesce(s.enabled AND s.runtime_ready,false) OR q.settings_revision<>s.revision OR q.instance<>s.instance OR q.sender_phone<>s.sender_phone OR q.inbound_id IS NOT NULL OR l.stage<>'lead-novo' OR l.pipeline_id IS NOT NULL OR public.first_contact_number(CASE WHEN length(regexp_replace(l.whatsapp,'[^0-9]','','g')) IN (10,11) THEN '55'||regexp_replace(l.whatsapp,'[^0-9]','','g') ELSE regexp_replace(l.whatsapp,'[^0-9]','','g') END)<>q.contact_key OR NOT public.commercial_knowledge_access(s.authorized_by,'crm:1') OR NOT EXISTS(SELECT 1 FROM public.portal_admin_channels WHERE user_id=s.authorized_by AND instance=s.instance AND company_key='crm:1' AND public.first_contact_number(canonical_phone)=public.first_contact_number(s.sender_phone)) OR EXISTS(SELECT 1 FROM public.portal_admin_channels WHERE instance=s.instance AND company_key<>'crm:1') THEN UPDATE public.first_contact_sequences SET state='cancelled',reason='authorization_or_lead_changed',completed_at=now() WHERE id=p_id; PERFORM public.arm_first_contact_queue(); RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM public.whatsapp_messages WHERE instance=q.instance AND NOT from_me AND public.first_contact_number(phone)=q.contact_key AND sent_at>=q.started_at) THEN PERFORM public.cancel_first_contact(q.instance,q.phone,'existing-inbound',now(),false); RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM public.first_contact_sequences WHERE instance=q.instance AND state='sending' AND id<>q.id) THEN RETURN NULL; END IF;
 b:=CASE q.next_step WHEN 1 THEN 'Olá, '||q.first_name||'! Tudo bem?' WHEN 2 THEN 'Vi que você preencheu nosso formulário sobre nossa agência de tráfego pago e marketing digital, onde apresentamos nosso plano atual.' WHEN 3 THEN 'Estamos com um plano de teste disponível para que você possa conhecer nosso serviço de tráfego pago durante 30 dias.' WHEN 4 THEN 'Gostaria de saber se você já investiu em tráfego pago?' END;
 INSERT INTO public.first_contact_attempts(sequence_id,step,body) VALUES(q.id,q.next_step,b) ON CONFLICT DO NOTHING; IF NOT FOUND THEN RETURN NULL; END IF;
 UPDATE public.first_contact_sequences SET state='sending',lease_id=p_lease,lease_until=now()+interval '45 seconds' WHERE id=q.id;
 RETURN jsonb_build_object('id',q.id,'step',q.next_step,'body',b,'phone',q.phone,'instance',q.instance,'senderPhone',q.sender_phone);
END $$;
REVOKE ALL ON FUNCTION public.claim_first_contact(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_first_contact(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.revalidate_first_contact(p_id uuid,p_lease uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.first_contact_settings; q public.first_contact_sequences; l public.leads; BEGIN
 SELECT * INTO s FROM public.first_contact_settings WHERE company_key='crm:1' FOR UPDATE; SELECT * INTO q FROM public.first_contact_sequences WHERE id=p_id FOR UPDATE; SELECT * INTO l FROM public.leads WHERE id=q.lead_id FOR UPDATE;
 RETURN coalesce(q.state='sending' AND q.lease_id=p_lease AND q.lease_until>now() AND s.enabled AND s.runtime_ready AND s.revision=q.settings_revision AND s.instance=q.instance AND s.sender_phone=q.sender_phone AND q.inbound_id IS NULL AND l.stage='lead-novo' AND l.pipeline_id IS NULL AND public.first_contact_number(CASE WHEN length(regexp_replace(l.whatsapp,'[^0-9]','','g')) IN (10,11) THEN '55'||regexp_replace(l.whatsapp,'[^0-9]','','g') ELSE regexp_replace(l.whatsapp,'[^0-9]','','g') END)=q.contact_key AND public.commercial_knowledge_access(s.authorized_by,'crm:1') AND EXISTS(SELECT 1 FROM public.portal_admin_channels WHERE user_id=s.authorized_by AND instance=s.instance AND company_key='crm:1' AND public.first_contact_number(canonical_phone)=public.first_contact_number(s.sender_phone)) AND NOT EXISTS(SELECT 1 FROM public.portal_admin_channels WHERE instance=s.instance AND company_key<>'crm:1') AND NOT EXISTS(SELECT 1 FROM public.whatsapp_messages WHERE instance=q.instance AND NOT from_me AND public.first_contact_number(phone)=q.contact_key AND sent_at>=q.started_at),false);
END $$;
REVOKE ALL ON FUNCTION public.revalidate_first_contact(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.revalidate_first_contact(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.finish_first_contact(p_id uuid,p_lease uuid,p_state text,p_provider text,p_at timestamptz,p_error text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.first_contact_settings; q public.first_contact_sequences; a public.first_contact_attempts; l public.leads; BEGIN
 SELECT * INTO s FROM public.first_contact_settings WHERE company_key='crm:1' FOR UPDATE; SELECT * INTO q FROM public.first_contact_sequences WHERE id=p_id FOR UPDATE;
 IF q.id IS NULL OR q.lease_id IS DISTINCT FROM p_lease THEN RETURN false; END IF;
 SELECT * INTO a FROM public.first_contact_attempts WHERE sequence_id=q.id AND step=q.next_step FOR UPDATE; IF a.id IS NULL THEN RETURN false; END IF; IF a.state='accepted' THEN RETURN true; END IF;
 IF p_state NOT IN ('accepted','failed','unknown') THEN RAISE EXCEPTION 'invalid_state'; END IF; IF p_state='accepted' AND (length(coalesce(p_provider,'')) NOT BETWEEN 1 AND 200 OR p_at IS NULL) THEN RAISE EXCEPTION 'invalid_receipt'; END IF;
 UPDATE public.first_contact_attempts SET state=p_state,provider_id=p_provider,accepted_at=p_at,error_code=left(p_error,160) WHERE id=a.id;
 IF p_state<>'accepted' THEN UPDATE public.first_contact_sequences SET state=CASE WHEN state='cancelled' THEN state ELSE p_state END,reason=coalesce(reason,left(p_error,160)),completed_at=now() WHERE id=q.id; PERFORM public.arm_first_contact_queue(); RETURN true; END IF;
 INSERT INTO public.whatsapp_messages(message_id,instance,phone,remote_jid,phone_key,from_me,body,sent_at,send_state,accepted_at) VALUES(p_provider,q.instance,q.phone,q.phone||'@s.whatsapp.net',CASE WHEN q.phone LIKE '55%' THEN substring(q.phone,3,2)||right(q.phone,8) ELSE right(q.phone,10) END,true,a.body,p_at,'accepted',p_at) ON CONFLICT(message_id) DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM public.whatsapp_messages WHERE message_id=p_provider AND instance=q.instance AND from_me AND body=a.body AND public.first_contact_number(phone)=q.contact_key) THEN RAISE EXCEPTION 'receipt_collision'; END IF;
 IF q.state='cancelled' OR NOT s.enabled OR q.settings_revision<>s.revision OR q.inbound_id IS NOT NULL THEN PERFORM public.arm_first_contact_queue(); RETURN true; END IF;
 SELECT * INTO l FROM public.leads WHERE id=q.lead_id FOR UPDATE;
 IF l.stage<>'lead-novo' OR l.pipeline_id IS NOT NULL OR NOT public.commercial_knowledge_access(s.authorized_by,'crm:1') OR public.first_contact_number(CASE WHEN length(regexp_replace(l.whatsapp,'[^0-9]','','g')) IN (10,11) THEN '55'||regexp_replace(l.whatsapp,'[^0-9]','','g') ELSE regexp_replace(l.whatsapp,'[^0-9]','','g') END)<>q.contact_key OR EXISTS(SELECT 1 FROM public.whatsapp_messages WHERE instance=q.instance AND NOT from_me AND public.first_contact_number(phone)=q.contact_key AND sent_at>=q.started_at) THEN UPDATE public.first_contact_sequences SET state='cancelled',reason='lead_or_authorization_changed',completed_at=now() WHERE id=q.id;
 ELSIF q.next_step=4 THEN IF (SELECT count(*) FROM public.first_contact_attempts WHERE sequence_id=q.id AND state='accepted')<>4 THEN RAISE EXCEPTION 'incomplete_sequence'; END IF;
 UPDATE public.leads SET stage='tentando-contato',history=coalesce(history,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('id','first-contact-complete-'||q.id::text,'date',now(),'text','Lead Novo → Tentando Contato. Quatro mensagens de primeiro contato aceitas pela Evolution; entrega não confirmada.','kind','first_contact_complete')) WHERE id=l.id;
 UPDATE public.first_contact_sequences SET state='completed',next_step=5,completed_at=now(),moved_at=now() WHERE id=q.id;
 ELSE UPDATE public.first_contact_sequences SET state='pending',next_step=next_step+1,due_at=now()+make_interval(secs=>s.interval_seconds),lease_id=NULL,lease_until=NULL WHERE id=q.id; END IF; PERFORM public.arm_first_contact_queue(); RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.finish_first_contact(uuid,uuid,text,text,timestamptz,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finish_first_contact(uuid,uuid,text,text,timestamptz,text) TO service_role;
CREATE TABLE public.gravon_outbound_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inbound_id text NOT NULL UNIQUE,instance text NOT NULL,remote_jid text NOT NULL,body text NOT NULL,state text NOT NULL DEFAULT 'sending' CHECK(state IN ('sending','accepted','failed','unknown')),provider_id text,echo_id text,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.gravon_outbound_reservations TO service_role; REVOKE ALL ON public.gravon_outbound_reservations FROM anon,authenticated; ALTER TABLE public.gravon_outbound_reservations ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.claim_gravon_reserved_echo(p_instance text,p_jid text,p_id text,p_body text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.gravon_outbound_reservations; BEGIN
 SELECT * INTO r FROM public.gravon_outbound_reservations WHERE instance=p_instance AND remote_jid=p_jid AND (provider_id=p_id OR echo_id=p_id OR (provider_id IS NULL AND echo_id IS NULL AND state IN ('sending','unknown') AND body=p_body)) ORDER BY created_at LIMIT 1 FOR UPDATE;
 IF r.id IS NULL THEN RETURN false; END IF; IF r.echo_id IS NULL THEN UPDATE public.gravon_outbound_reservations SET echo_id=p_id WHERE id=r.id; END IF; RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.claim_gravon_reserved_echo(text,text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_gravon_reserved_echo(text,text,text,text) TO service_role;